import {VERSION, PARTS, PILOTS, MECHANICS, CIRCUITS, SUPPLIES, MARKET, SLOTS, SLOT_NAMES, LABELS, ATTR, newTeam, attributes, scores, supplyNeeds, marketPrice, fixedCost, inventory, operating, checklist, compareTests, simulate} from '../shared/game.js';
import './style.css';

const app=document.getElementById('app');
const q=new URLSearchParams(location.search);
const ui={roomId:q.get('room')||localStorage.getItem('ft_room'),projectionToken:q.get('projection'),screen:'welcome',slot:'engine',testView:'summary',toast:'',connectionError:'',teacherRooms:[],busy:false,reduceMotion:localStorage.getItem('ft_reduce')==='1',projectionRefresh:sessionStorage.getItem('ft_projection')};
ui.demo={pilot:'PILOT_1',mechanic:'MECH_1',parts:Object.fromEntries(SLOTS.map(s=>[s,PARTS[s][0].id]))};
let state=null,user=null,poll=null,polling=false,serverOffset=0,qteQueue=Promise.resolve();
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cr=n=>`${Number(n||0).toLocaleString('pt-BR')} Cr`;
const sec=n=>`${Number(n||0).toFixed(2).replace('.',',')} s`;
const id=()=>crypto.randomUUID();
const toast=(m)=>{ui.toast=m;render();setTimeout(()=>{if(ui.toast===m){ui.toast='';render();}},4500)};
const button=(label,action,extra='',disabled=false,reason='')=>`<button type="button" data-action="${action}" ${extra} ${disabled?'disabled':''} title="${esc(reason)}">${label}</button>${disabled&&reason?`<small class="blocked-reason">${esc(reason)}</small>`:''}`;
async function auth(){try{const result=await call('session');user=result.user;}catch{user=null;}}
async function loadTeacherRooms(){try{ui.teacherRooms=(await call('teacher-rooms')).rooms;ui.connectionError='';}catch(e){ui.teacherRooms=[];ui.connectionError=e.message||'Não foi possível listar as salas.';}}
async function openRoom(roomId){state=null;ui.roomId=roomId;localStorage.setItem('ft_room',roomId);ui.screen='teacher';await load();}
async function call(action,payload={},requestId=null){
  const args={action,...payload};if(!['state','export-session','create-room','teacher-rooms'].includes(action))args.requestId=requestId||id();
  for(let attempt=0;attempt<3;attempt++){
    const response=await fetch('/api/game',{method:'POST',headers:{'content-type':'application/json'},credentials:'include',body:JSON.stringify(args)});
    const data=await response.json().catch(()=>null);
    if(!data?.ok){if(data?.code==='CONFLICT_RELOAD_REQUIRED'&&attempt<2)continue;const error=Error(data?.message||data?.code||'Falha na ação.');error.code=data?.code;throw error;}
    return data.data;
  }
}
async function load(){if(!ui.roomId)return;try{const started=Date.now(),next=await call('state',{roomId:ui.roomId,projectionToken:ui.projectionToken}),received=Date.now();if(!state||next.room.id!==state.room.id||next.room.version>=state.room.version){state=next;serverOffset=next.serverTime-(started+received)/2;}ui.connectionError='';if(ui.screen==='welcome')ui.screen=ui.projectionToken?'projection':state.room.teacherId===user?.id?'teacher':'overview';if(!document.activeElement?.matches('input,textarea,select'))render();}catch(e){if(ui.projectionToken){app.innerHTML=`<main class="centered"><h1>Link de projeção inválido</h1><p>${esc(e.message)}</p></main>`;}else if(e.code==='ROOM_NOT_FOUND'){ui.roomId=null;localStorage.removeItem('ft_room');state=null;ui.connectionError='Sala não encontrada.';render();}else if(e.code==='TEAM_REMOVED'){ui.roomId=null;localStorage.removeItem('ft_room');state=null;ui.screen='welcome';ui.connectionError='';toast(e.message);}else{ui.connectionError=e.message||'Falha ao atualizar a sala.';if(!document.activeElement?.matches('input,textarea,select'))render();}}}
async function mutate(action,payload={}){if(ui.busy)return;ui.busy=true;render();try{const result=await call(action,{roomId:ui.roomId,...payload});await load();return result;}catch(e){toast(e.message);return null;}finally{ui.busy=false;render();}}
function setScreen(screen){ui.screen=screen;render();}
function topbar(){const room=state?.room,team=state?.own;return `<header class="topbar"><div class="brand" data-action="home"><span class="brand-mark">FT</span><span><strong>FÓRMULA TECH</strong><small>Laboratório de decisões</small></span></div>${room?`<div class="room-chip"><span class="dot"></span>${esc(room.name)} <span class="muted">· ${esc(CIRCUITS[room.circuitId].name)}</span></div>`:''}<div class="top-actions">${team?`<div class="budget"><small>Saldo disponível</small><strong>${cr(team.wallet)}</strong></div>`:''}${room?`<button class="icon-btn" data-action="rules" title="Abrir regras">?</button><button class="icon-btn" data-action="motion" title="Reduzir movimento">${ui.reduceMotion?'◼':'◉'}</button>`:''}</div></header>`;}
function welcome(){return `<section class="hero"><div class="hero-copy"><div class="hero-kicker">Engenharia, estratégia e corrida</div><h1>Construa a equipe.<br>Teste suas ideias.<br><em>Ganhe na pista.</em></h1><p>Cada decisão muda o carro. Você tem 1.200 créditos, um circuito para entender e uma corrida contra a turma.</p><div class="hero-actions">${button('Entrar na sala','show-join','class="primary"')}${button('Acesso do professor','show-teacher','class="secondary"')}</div><div class="steps"><span>01 Monte</span><span>02 Teste</span><span>03 Melhore</span><span>04 Corra</span></div></div><div class="hero-visual"><div class="speedline"></div><div class="hero-number">01</div><svg viewBox="0 0 560 410" aria-label="Ilustração de carro de corrida"><path d="M65 280 C155 330 305 355 478 295" fill="none" stroke="#2d4b64" stroke-width="10"/><path d="M72 291 C192 350 358 340 485 260" fill="none" stroke="#fb6b55" stroke-width="3" stroke-dasharray="13 13"/><g transform="translate(90 152) rotate(-10 210 100)"><path d="M70 140 L135 83 L345 78 L428 135 L403 160 L80 163Z" fill="#ed604f"/><path d="M132 86 L170 49 L288 50 L345 79Z" fill="#bb3d3c"/><path d="M166 56 L281 57 L324 81 L145 83Z" fill="#162638"/><path d="M80 138 L45 145 L45 165 L116 163Z M399 137 L460 142 L460 162 L386 163Z" fill="#a5c3d0"/><circle cx="137" cy="167" r="37" fill="#121b27" stroke="#638298" stroke-width="9"/><circle cx="365" cy="167" r="37" fill="#121b27" stroke="#638298" stroke-width="9"/><path d="M196 76 L268 74" stroke="#ffe1b5" stroke-width="8"/><text x="230" y="135" fill="white" font-size="42" font-weight="900">FT</text></g></svg><div class="visual-caption">A pista recompensa escolhas inteligentes.</div></div></section><section class="welcome-footer"><div><strong>Seu laboratório começa na garagem.</strong><span>Uma variável de cada vez. Um resultado para investigar.</span></div><button data-action="rules">Como funciona ↗</button></section>`;}
function join(){return `<section class="auth-layout"><div><div class="eyebrow">Aluno</div><h1>Entre na sua sala</h1><p>Use o código compartilhado pelo professor. Escolha um nome fictício para sua escuderia.</p><form id="join-form" class="form-card"><label>Código da sala<input name="code" maxlength="8" required autocomplete="off" placeholder="ABCD2345"></label><label>Nome da escuderia<input name="teamName" minlength="3" maxlength="20" required placeholder="Ex.: Falcões da Pista"></label><label>Cor do carro</label><div class="color-picker">${['#f05d5e','#44b6d7','#edbb4f','#c48bec','#6ed0a4','#ff8d53','#8caaed','#f38cb2'].map((c,i)=>`<label class="color-option" title="Cor ${i+1}"><input type="radio" name="color" value="${c}" ${i===0?'checked':''}><span style="--swatch:${c}"></span></label>`).join('')}</div><button class="primary wide" type="submit" ${ui.busy?'disabled':''}>Entrar na sala</button></form></div><div class="auth-aside"><strong>O jogo começa com 1.200 Cr.</strong><p>Monte um carro completo, faça dois testes e explique os resultados antes da corrida.</p><div class="mini-track">R · C · M · R · C · M</div></div></section>`;}
function teacherLogin(){return `<section class="auth-layout"><div><div class="eyebrow">Professor</div><h1>Comande a aula</h1><p>Acesso com sua conta de professor.</p><form id="login-form" class="form-card"><label>E-mail<input type="email" name="email" required autocomplete="username"></label><label>Senha<input type="password" name="password" required autocomplete="current-password"></label><button class="primary wide" type="submit">Entrar como professor</button></form></div><div class="auth-aside"><strong>Você define o ritmo.</strong><p>Abra a construção, libere os testes, anuncie o mercado e inicie cada bateria.</p></div></section>`;}
function createRoom(){return `<section class="content narrow"><div class="eyebrow">Painel do professor</div><h1>Prepare a corrida</h1>${ui.teacherRooms.length?`<article class="panel existing-rooms"><h2>Salas existentes</h2><p>Reabra uma sala para continuar a aula.</p>${ui.teacherRooms.map(room=>`<div class="existing-room"><div><strong>${esc(room.name)}</strong><small>${esc(room.phase)} · ${room.teamCount} escuderia(s) · ${new Date(room.createdAt).toLocaleString('pt-BR')}</small></div>${button('Abrir sala','open-room',`data-room="${room.id}" class="secondary"`)}</div>`).join('')}</article>`:''}<h2>Nova sala</h2><form id="create-form" class="form-card"><label>Nome da atividade<input name="name" required maxlength="80" value="Fórmula Tech — Turma A"></label><label>Circuito<select name="circuitId">${Object.entries(CIRCUITS).map(([id,c])=>`<option value="${id}">${c.name} — ${c.description}</option>`).join('')}</select></label><div class="form-row"><label>Participantes (até 20)<input type="number" name="maxPlayers" min="1" max="20" value="10"></label><label>Carros por bateria<input type="number" name="carsPerHeat" min="1" max="5" value="5"></label></div><label>Modo<select name="mode"><option value="standard">60 minutos</option><option value="extended">Estendido</option></select></label><label class="check"><input type="checkbox" name="qteEnabled" checked> Habilitar desafios de ultrapassagem</label><button class="primary wide" type="submit" ${ui.busy?'disabled':''}>Criar sala</button></form></section>`;}
function nav(){const teacher=state.room.teacherId===user?.id,items=teacher?[['teacher','Painel'],['rooms','Salas'],['demo','Demonstração'],['race','Corrida'],['results','Resultados']]:[['overview','Desafio'],['team','Equipe'],['garage','Garagem'],['market','Mercado'],['tests','Testes'],['prep','Preparação'],['race','Corrida'],['results','Resultados']];return `<nav class="nav"><div class="nav-inner">${items.map(([s,l])=>`<button class="${ui.screen===s?'active':''}" data-action="nav" data-screen="${s}">${l}</button>`).join('')}</div></nav>`;}
function trackProfile(){const c=CIRCUITS[state.room.circuitId];return `<div class="track-profile">${c.sectors.map((s,i)=>`<div class="sector ${s.toLowerCase()}"><small>${String(i+1).padStart(2,'0')}</small><strong>${{R:'RETA',C:'CURVA',M:'MISTO'}[s]}</strong></div>`).join('')}</div>`;}
function overview(){return `<section class="content"><div class="page-head"><div><div class="eyebrow">Sua missão</div><h1>O circuito decide o projeto.</h1><p>${esc(CIRCUITS[state.room.circuitId].description)} A menor soma de tempo em três voltas vence.</p></div><div class="phase-tag">Etapa: ${esc(state.room.phase)}</div></div>${trackProfile()}<div class="split"><article class="feature"><h2>1.200 créditos. Seis decisões.</h2><p>Contrate um piloto e um mecânico. Depois escolha motor, chassi, pneus, suspensão, aerodinâmica e freios. Guarde créditos para combustível e pneus.</p>${button('Montar minha equipe','nav','data-screen="team" class="primary"')}</article><article class="feature pale"><h2>Não adivinhe. Teste.</h2><p>O primeiro e o segundo teste são grátis. Registre uma hipótese e compare os tempos por setor. Você pode manter ou alterar o projeto.</p>${button('Conhecer o Centro de Testes','nav','data-screen="tests" class="secondary"')}</article></div></section>`;}
function statStrip(team){const a=attributes(team),op=operating(team,state.room.market);return `<div class="stat-strip"><div><small>Investimento fixo</small><strong>${cr(fixedCost(team))}</strong></div><div><small>Operação mínima</small><strong>${cr(op.minimum)}</strong></div><div><small>Falta comprar</small><strong>${cr(op.additional)}</strong></div><div><small>Margem após preparo</small><strong>${cr(team.wallet-op.additional)}</strong></div></div><div class="attributes">${ATTR.map(k=>`<div class="attr"><span>${LABELS[k]}</span><div class="meter"><i style="width:${a[k]}%"></i></div><strong>${a[k]}</strong></div>`).join('')}</div>`;}
function selectionCard(item,current,action,extra='',locked='',meta=''){
  let preview='';const t=state?.own;
  if(action==='choose-part'&&t){
    const before=scores(attributes(t)),after=scores(attributes({...t,parts:{...t.parts,[ui.slot]:item.id}})),balance=t.wallet+(t.receipts[ui.slot]||0)-item.price;
    preview=`<div class="part-preview"><span>Reta ${before.R.toFixed(0)} → ${after.R.toFixed(0)}</span><span>Curva ${before.C.toFixed(0)} → ${after.C.toFixed(0)}</span><span>Misto ${before.M.toFixed(0)} → ${after.M.toFixed(0)}</span><span>Saldo após: ${cr(balance)}</span></div>`;
    if(balance<0&&!current&&!locked)locked=`Saldo insuficiente: faltam ${cr(-balance)}.`;
  }
  if(action==='choose-staff'&&t){
    const kind=item.id.startsWith('PILOT')?'pilot':'mechanic',balance=t.wallet+(t.receipts[kind]||0)-item.price;
    if(balance<0&&!current&&!locked)locked=`Saldo insuficiente: faltam ${cr(-balance)}.`;
    if(kind==='mechanic'&&!current&&!locked&&SLOTS.some(s=>(PARTS[s].find(p=>p.id===t.parts[s])?.level||0)>item.level))locked='Troque as peças de nível superior antes de contratar este mecânico.';
  }
  return `<article class="select-card ${current?'selected':''} ${locked?'locked':''}"><div class="select-top"><h3>${esc(item.name)}</h3><strong>${cr(item.price)}</strong></div><p>${esc(item.description||meta)}</p>${preview}<div class="card-foot"><span>${meta?esc(meta):''}</span>${button(current?'Instalado':'Escolher',action,extra,current||!!locked,locked)}</div></article>`;
}
function team(){const t=state.own;if(!t)return `<section class="content"><p>Entre na sala como aluno para montar sua equipe.</p></section>`;const editable=['TEAM_BUILD','TESTING'].includes(state.room.phase);return `<section class="content"><div class="page-head"><div><div class="eyebrow">Minha equipe</div><h1>Quem cuida do carro?</h1><p>O mecânico libera tecnologias. O piloto melhora controle e confiabilidade, mas sua reação no duelo continua sendo sua.</p></div></div>${statStrip(t)}<div class="catalog-heading"><h2>Piloto</h2><p>Escolha exatamente um.</p></div><div class="card-grid">${PILOTS.map(x=>selectionCard(x,t.pilot===x.id,'choose-staff',`data-kind="pilot" data-id="${x.id}"`,editable?'':'Etapa encerrada')).join('')}</div><div class="catalog-heading"><h2>Mecânico principal</h2><p>Peças exigem nível igual ou inferior ao do mecânico.</p></div><div class="card-grid">${MECHANICS.map(x=>selectionCard(x,t.mechanic===x.id,'choose-staff',`data-kind="mechanic" data-id="${x.id}"`,editable?'':'Etapa encerrada',`Nível técnico ${x.level}`)).join('')}</div><div class="catalog-heading"><h2>Auxiliar</h2><p>Opcional: +5 confiabilidade e 30% de desconto em reparos novos.</p></div><div class="inline-action"><span>${t.aux?'Contratado':'Não contratado'} · 80 Cr</span>${button(t.aux?'Dispensar auxiliar':'Contratar auxiliar','choose-aux','',!editable,'Etapa encerrada')}</div><div class="bottom-action">${button('Ir para a garagem','nav','data-screen="garage" class="primary"')}</div></section>`;}
function garage(){const t=state.own;if(!t)return `<section class="content"><p>Garagem disponível para alunos.</p></section>`;const editable=['TEAM_BUILD','TESTING'].includes(state.room.phase),mechanic=MECHANICS.find(m=>m.id===t.mechanic),level=mechanic?.level||0;return `<section class="content"><div class="page-head"><div><div class="eyebrow">Garagem</div><h1>Cada peça muda a corrida.</h1><p>Escolha uma peça por categoria. Compare o ganho no circuito com o custo e o consumo.</p></div><strong class="progress-count">${SLOTS.filter(s=>t.parts[s]).length}/6 instaladas</strong></div>${statStrip(t)}<div class="garage-layout"><div class="garage-preview"><div class="car-top" style="--car:${t.color}"><div class="front-wing"></div><div class="body"></div><div class="cockpit"></div><div class="wheel w1"></div><div class="wheel w2"></div><div class="wheel w3"></div><div class="wheel w4"></div><div class="rear-wing"></div><strong>${String(t.number).padStart(2,'0')}</strong></div><h2>${esc(t.name)}</h2><p>Seu carro antes da próxima decisão.</p><div class="score-chips">${Object.entries(scores(attributes(t))).map(([k,v])=>`<span>${{R:'Reta',C:'Curva',M:'Misto'}[k]} <b>${v.toFixed(0)}</b></span>`).join('')}</div></div><div class="garage-options"><div class="slot-tabs">${SLOTS.map(s=>`<button class="${ui.slot===s?'active':''}" data-action="slot" data-slot="${s}">${SLOT_NAMES[s]} ${t.parts[s]?'✓':''}</button>`).join('')}</div><div class="card-grid compact">${PARTS[ui.slot].map(x=>{const locked=x.level>level?`Exige mecânico nível ${x.level}; o seu é nível ${level}.`:!editable?'Etapa encerrada':'';const vector=x.vector.map((v,i)=>v?`${v>0?'+':''}${v} ${LABELS[ATTR[i]]}`:null).filter(Boolean).join(' · ');return selectionCard({...x,description:vector},t.parts[ui.slot]===x.id,'choose-part',`data-slot="${ui.slot}" data-id="${x.id}"`,locked,`Nível ${x.level}`)}).join('')}</div></div></div><div class="bottom-action">${button('Ir ao mercado','nav','data-screen="market" class="primary"')}</div></section>`;}
function market(){const t=state.own;if(!t)return `<section class="content"><p>Mercado disponível para alunos.</p></section>`;const editable=['TEAM_BUILD','TESTING'].includes(state.room.phase),need=supplyNeeds(t),op=operating(t,state.room.market);return `<section class="content"><div class="page-head"><div><div class="eyebrow">Mercado · ${state.room.market}</div><h1>Preparar também custa.</h1><p>Os preços mudam para toda a sala quando o professor anuncia um evento. Devoluções recebem o valor originalmente pago.</p></div><div class="phase-tag">${state.room.market}</div></div>${statStrip(t)}<div class="market-grid">${Object.entries(SUPPLIES).map(([kind,x])=>{const price=marketPrice(kind,state.room.market,t.aux),have=inventory(t,kind),required=need[kind];return `<article class="supply-card"><div class="supply-icon">${{fuel:'◉',tires:'◎',repair:'✚'}[kind]}</div><h2>${x.name}</h2><strong class="supply-price">${cr(price)} <small>/ unidade</small></strong><p>Em estoque: <b>${have}</b> · Necessário: <b>${required}</b></p><div class="supply-controls"><button data-action="buy-supply" data-kind="${kind}" ${!editable?'disabled':''}>Comprar 1</button>${kind==='repair'?button(t.repairAssigned?'Retirar da corrida':'Usar na corrida','assign-repair','',!editable||(!t.repairAssigned&&have<1),have<1?'Compre um kit primeiro':''):''}</div></article>`}).join('')}</div><div class="split"><article class="feature"><h2>Cobertura da classificatória</h2><p>Combustível: ${inventory(t,'fuel')}/${need.fuel} · Pneus: ${inventory(t,'tires')}/${need.tires}</p><p>Faltam ${cr(op.additional)} em compras obrigatórias no preço atual.</p></article><article class="feature pale"><h2>Seus lotes</h2>${t.lots.length?t.lots.map(l=>`<div class="lot"><span>${SUPPLIES[l.kind].name} · ${l.quantity} un. · pago ${cr(l.paid)}/un.</span>${button('Devolver 1','refund-supply',`data-lot="${l.id}"`,!editable)}</div>`).join(''):'<p>Você ainda não comprou suprimentos.</p>'}</article></div><div class="bottom-action">${button('Ir para os testes','nav','data-screen="tests" class="primary"')}</div></section>`;}
function testReport(test){if(!test)return `<div class="empty">Monte o carro e espere o professor abrir os testes.</div>`;const r=test.result;const previous=state.own.tests.at(-2),comparison=compareTests(previous,test);return `<div class="report-head"><div><small>Teste #${String(test.number).padStart(2,'0')}</small><strong>${sec(r.total)}</strong><span>Uma volta · ${CIRCUITS[r.circuitId].name}</span></div><div>${comparison?`<strong class="${comparison.delta>=0?'positive':'negative'}">${comparison.delta>=0?'-':'+'}${sec(Math.abs(comparison.delta))}</strong><small>em relação ao teste anterior</small>`:''}</div></div><div class="report-tabs">${[['summary','Visão geral'],['logs','Logs'],['compare','Comparar']].map(([v,l])=>`<button class="${ui.testView===v?'active':''}" data-action="test-view" data-view="${v}">${l}</button>`).join('')}</div>${ui.testView==='summary'?`<div class="sector-chart">${r.sectors.map(s=>`<div class="chart-row"><span>${s.index} · ${{R:'Reta',C:'Curva',M:'Misto'}[s.type]}</span><div><i style="width:${Math.min(100,s.seconds/10*100)}%"></i></div><strong>${sec(s.seconds)}</strong></div>`).join('')}</div><div class="alerts">${r.alerts.length?r.alerts.map(x=>`<p>⚑ ${esc(x)}</p>`).join(''):'<p>Sem gargalos críticos detectados. Compare os setores para buscar ganho marginal.</p>'}</div>`:ui.testView==='logs'?`<div class="log-list">${r.sectors.map(s=>`<div><span>Setor ${s.index} · ${{R:'Reta',C:'Curva',M:'Misto'}[s.type]}</span><strong>${sec(s.seconds)}</strong><small>Score ${s.score.toFixed(1)} · referência ${sec(s.reference)} · diferença ${s.delta>=0?'+':''}${sec(s.delta)}</small></div>`).join('')}<p>Investigue o setor ${r.bottleneck.sector}: diferença ${sec(r.bottleneck.delta)} em relação à referência.</p></div>`:`<div class="comparison">${comparison?`<h3>O que mudou?</h3><p>${comparison.changed.length?comparison.changed.map(x=>x.replace('parts.','')).join(', '):'Nenhum item mudou.'}</p><div class="comparison-metrics"><span>Tempo anterior <b>${sec(previous.result.total)}</b></span><span>Tempo atual <b>${sec(test.result.total)}</b></span><span>Diferença <b>${sec(comparison.delta)} (${comparison.percent.toFixed(1)}%)</b></span><span>Custo fixo adicional <b>${cr(comparison.cost)}</b></span></div><p>${comparison.cost>0?`${comparison.marginal.toFixed(3)} segundo(s) ganho(s) por 100 Cr adicionais.`:comparison.cost===0?comparison.changed.length?'Alteração sem custo fixo adicional.':'Mesmo projeto: resultado reproduzido sem variação.':`Economia de ${cr(-comparison.cost)}; compare também o tempo.`}</p>${comparison.changed.length>1?'<p>Você alterou vários itens; fica mais difícil atribuir a diferença a uma única escolha.</p>':''}`:'<p>Faça o segundo teste para comparar. Você pode manter o mesmo projeto.</p>'}</div>`}`;}
function tests(){const t=state.own;if(!t)return `<section class="content"><p>Testes disponíveis para alunos.</p></section>`;const enabled=state.room.phase==='TESTING',test=t.tests.at(-1),a=t.analysis;return `<section class="content"><div class="page-head"><div><div class="eyebrow">Centro de Testes</div><h1>Uma hipótese. Dois testes. Uma conclusão.</h1><p>Teste uma volta em condições iguais. O cronômetro vem da mesma engine usada na corrida.</p></div><div class="phase-tag">${t.tests.length<2?`${2-t.tests.length} grátis`:'12 Cr / teste'}</div></div><div class="test-layout"><div><div class="test-control"><div><h2>Volta de laboratório</h2><p>${CIRCUITS[state.room.circuitId].name} · 6 setores · sem consumo de suprimentos</p></div>${button('Executar teste','run-test','class="primary"',!enabled||ui.busy,!enabled?'O professor ainda não abriu os testes.':'')}</div>${testReport(test)}</div><aside class="analysis-panel"><h2>Desafio do Engenheiro</h2><p>Registre sua hipótese, faça dois testes e justifique a conclusão com um número do relatório. Você pode manter o projeto no segundo teste.</p><div class="challenge-step"><span>1</span><div><strong>Primeiro teste</strong><small>${t.tests[0]?sec(t.tests[0].result.total):'Pendente'}</small></div></div><form id="hypothesis-form"><label>Gargalo identificado<select name="target" ${!t.tests.length?'disabled':''}><option value="">Escolha</option><option value="R" ${a.target==='R'?'selected':''}>Retas</option><option value="C" ${a.target==='C'?'selected':''}>Curvas</option><option value="M" ${a.target==='M'?'selected':''}>Mistos</option></select></label><label>Decisão para o próximo teste<input name="change" maxlength="80" value="${esc(a.change||'')}" placeholder="Ex.: manter o projeto ou trocar os pneus" ${!t.tests.length?'disabled':''}></label><label>O que espero observar e por quê<input name="reason" maxlength="160" value="${esc(a.reason||'')}" placeholder="Ex.: confirmar o tempo ou melhorar o controle" ${!t.tests.length?'disabled':''}></label><button type="submit" ${!t.tests.length?'disabled':''}>Salvar hipótese</button></form><div class="challenge-step"><span>2</span><div><strong>Faça o segundo teste</strong><small>${t.tests[1]?sec(t.tests[1].result.total):'Pendente'}</small></div></div><p class="muted">${t.tests.length<2?'A conclusão será liberada após o segundo teste.':'Segundo teste concluído. Registre a conclusão com uma métrica.'}</p><form id="conclusion-form"><label>Resultado<select name="evaluation" ${t.tests.length<2?'disabled':''}><option value="">Escolha</option><option value="improved" ${a.evaluation==='improved'?'selected':''}>Melhorou</option><option value="partially" ${a.evaluation==='partially'?'selected':''}>Melhorou parcialmente</option><option value="not_improved" ${a.evaluation==='not_improved'?'selected':''}>Não melhorou</option><option value="unchanged" ${a.evaluation==='unchanged'?'selected':''}>Sem diferença</option></select></label><label>Justifique com um número<input name="evidence" maxlength="240" value="${esc(a.evidence||'')}" placeholder="Ex.: os dois testes marcaram 8,2 s no setor 2" ${t.tests.length<2?'disabled':''}></label><button type="submit" ${t.tests.length<2?'disabled':''}>Salvar conclusão</button></form></aside></div><div class="bottom-action">${button('Ver preparação','nav','data-screen="prep" class="primary"')}</div></section>`;}
function prep(){const t=state.own;if(!t)return `<section class="content"><p>Preparação disponível para alunos.</p></section>`;const missing=checklist(t);return `<section class="content narrow"><div class="eyebrow">Preparação</div><h1>Seu carro pode largar?</h1><p>Confira cada condição. O professor travará as equipes antes da bateria.</p><div class="checklist">${[['Equipe e 6 peças',!!(t.pilot&&t.mechanic&&SLOTS.every(s=>t.parts[s])),'garage'],['Dois testes realizados',t.tests.length>=2,'tests'],['Hipótese e conclusão',!!(t.analysis.target&&t.analysis.change&&t.analysis.reason&&t.analysis.evaluation&&t.analysis.evidence),'tests'],['Combustível e pneus',inventory(t,'fuel')>=supplyNeeds(t).fuel&&inventory(t,'tires')>=supplyNeeds(t).tires,'market']].map(([name,ok,screen])=>`<button data-action="nav" data-screen="${screen}" class="check-item"><span class="${ok?'done':'pending'}">${ok?'✓':'!'}</span><strong>${name}</strong><small>${ok?'Concluído':'Abrir e resolver'}</small></button>`).join('')}</div>${missing.length?`<div class="notice"><strong>Faltam ${missing.length} condição(ões)</strong><ul>${missing.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:'<div class="notice success">Tudo pronto para a classificatória.</div>'}<div class="bottom-action">${button(t.ready?'Cancelar prontidão':'Pronto para correr','ready','class="primary"',(!t.ready&&!!missing.length)||state.room.phase!=='TESTING',state.room.phase!=='TESTING'?'Prontidão encerrada.':missing.join('; '))}</div></section>`;}
function teacher(){const r=state.room,teams=state.roster,heats=state.heats;const next={LOBBY:['TEAM_BUILD','Abrir construção'],TEAM_BUILD:['TESTING','Abrir testes'],TESTING:['LOCK_IN','Travar equipes'],FINAL:['RESULTS','Mostrar resultados']};return `<section class="content"><div class="page-head"><div><div class="eyebrow">Comando da aula</div><h1>${esc(r.name)}</h1><p>Código privado: <strong class="room-code">${esc(r.code)}</strong> · ${esc(CIRCUITS[r.circuitId].name)} · ${teams.length}/${r.maxPlayers} escuderias</p></div><div class="phase-tag">${esc(r.phase)}</div></div><div class="teacher-actions">${next[r.phase]?button(next[r.phase][1],'transition',`data-phase="${next[r.phase][0]}" class="primary"`,(r.phase==='TESTING'&&teams.some(t=>!t.ready))||(r.phase==='FINAL'&&heats.some(h=>h.type==='final'&&h.status!=='finished')),r.phase==='TESTING'?'Ainda há equipes não prontas.':'Conclua a final primeiro.'):''}${['TEAM_BUILD','TESTING'].includes(r.phase)&&r.market!=='M2'?button(`Anunciar ${r.market==='M0'?'M1':'M2'}`,'market-next','class="secondary"'):''}${r.phase==='LOCK_IN'?button('Criar baterias','build-heats','class="primary"'):''}${r.phase==='QUALIFYING'&&heats.filter(h=>h.type==='qualifier').every(h=>h.status==='finished')?button('Criar grande final','build-final','class="primary"'):''}${r.phase==='RESULTS'?button('Encerrar sala','transition','data-phase="CLOSED" class="secondary"'):''}${button('Exportar CSV','export','class="secondary"')}${ui.projectionRefresh?button('Abrir projeção','open-projection','class="secondary"'):''}</div><div class="teacher-grid"><article class="panel"><h2>Escuderias</h2><div class="table-wrap"><table><thead><tr><th>Equipe</th><th>Carro</th><th>Testes</th><th>Prontidão</th><th>Saldo</th><th>Ações</th></tr></thead><tbody>${teams.map(t=>{const full=state.roster.find(x=>x.id===t.id),privateTeam=state.teacherTeams?.find(x=>x.id===t.id);return `<tr><td><span class="team-dot" style="background:${t.color}"></span>${esc(t.name)}</td><td>${full.complete?'6 peças':'Incompleto'}</td><td>${t.tests}</td><td>${t.ready?'Pronto':'Pendente'}</td><td>${privateTeam?cr(privateTeam.wallet):'—'}</td><td class="team-action-cell">${['LOBBY','TEAM_BUILD','TESTING'].includes(r.phase)?button('Excluir','remove-team',`data-team="${t.id}" class="team-delete"`,ui.busy):'—'}</td></tr>`}).join('')}</tbody></table></div></article><article class="panel"><h2>Sequência da aula</h2><ol class="timeline"><li>Compartilhe o código e abra a construção.</li><li>Todos montam carro e compram suprimentos.</li><li>Abra testes; anuncie M1 no momento planejado.</li><li>Confira prontidão e trave equipes.</li><li>Crie baterias, inicie cada uma e depois a final.</li></ol></article></div><article class="panel"><h2>Baterias</h2>${heats.length?heats.map(h=>`<div class="heat-row"><div><strong>${h.type==='final'?'Grande final':`Classificatória ${h.number}`}</strong><small>${h.participants.map(p=>p.name).join(' · ')} · ${h.status}</small></div><div>${h.status==='created'?button('Iniciar bateria','race-command',`data-heat="${h.id}" data-command="start" class="primary"`):['running','countdown','qte_paused'].includes(h.status)?button('Pausar','race-command',`data-heat="${h.id}" data-command="pause"`):h.status==='admin_paused'?button('Retomar','race-command',`data-heat="${h.id}" data-command="resume"`):''}${['created','countdown'].includes(h.status)?button('Cancelar','race-command',`data-heat="${h.id}" data-command="cancel"`):''}</div></div>`).join(''):'<p>As baterias aparecem depois da trava.</p>'}</article><article class="panel"><h2>Eventos recentes</h2><div class="event-list">${state.events.slice().reverse().slice(0,10).map(e=>`<div><time>${new Date(e.at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</time><span>${esc(e.type)}</span></div>`).join('')||'<p>Nenhum evento ainda.</p>'}</div></article></section>`;}
function activeHeat(){const active=state.heats.find(h=>['countdown','running','qte_paused','admin_paused'].includes(h.status));if(active)return active;const last=state.heats.at(-1);return last?.status==='created'?last:state.heats.findLast(h=>h.status==='finished')||last;}
function race(){const h=activeHeat();if(!h)return `<section class="content narrow"><div class="eyebrow">Corrida</div><h1>Os carros ainda estão na garagem.</h1><p>O professor iniciará as baterias após todas as equipes ficarem prontas.</p></section>`;const elapsed=h.startAt?Math.max(0,Date.now()+serverOffset-h.startAt-h.pauseTotal-(h.pausedAt?Date.now()+serverOffset-h.pausedAt:0)):0,progress=h.duration?Math.min(1,elapsed/h.duration):0;const p=h.participants.slice().sort((a,b)=>(a.final??a.base+a.adjust)-(b.final??b.base+b.adjust));const myId=state.own?.id,e=h.event,eligible=e&&[e.front,e.behind].includes(myId)&&e.status==='open';return `<section class="content race-content"><div class="page-head"><div><div class="eyebrow">${h.type==='final'?'Grande final':`Classificatória ${h.number}`}</div><h1>${esc(CIRCUITS[state.room.circuitId].name)}</h1><p>${h.status==='countdown'?`Largada em ${Math.max(0,Math.ceil((h.startAt-Date.now()-serverOffset)/1000))}…`:h.status==='finished'?'Bandeirada! Resultado oficial calculado.':h.status==='admin_paused'?'Corrida pausada pelo professor.':'Três voltas. Seu carro corre conforme o projeto.'}</p></div><div class="phase-tag">${h.status==='finished'?'Resultado oficial':`${Math.min(3,Math.floor(progress*3)+1)}/3 voltas`}</div></div><div class="race-layout"><div class="track-panel"><svg id="race-svg" viewBox="0 0 760 460" role="img" aria-label="Pista com carros em movimento"><path id="track-path" d="M160 130 C85 130 45 190 70 290 C90 380 250 404 370 373 C465 350 585 410 680 330 C745 272 720 160 635 117 C535 67 450 92 370 130 C290 165 250 125 160 130Z" fill="none" stroke="#334657" stroke-width="55" stroke-linecap="round"/><path d="M160 130 C85 130 45 190 70 290 C90 380 250 404 370 373 C465 350 585 410 680 330 C745 272 720 160 635 117 C535 67 450 92 370 130 C290 165 250 125 160 130Z" fill="none" stroke="#8196a3" stroke-width="2" stroke-dasharray="14 16"/><g class="finish-line"><path d="M145 104 L145 155" stroke="white" stroke-width="5" stroke-dasharray="6 6"/></g>${h.participants.map((x,i)=>`<g class="race-car" data-car="${x.teamId}" transform="translate(150 130)"><circle r="17" fill="${x.color}" stroke="#fff" stroke-width="3"/><text y="5" text-anchor="middle" fill="#101723" font-size="13" font-weight="900">${x.number}</text></g>`).join('')}</svg><div class="track-overlay"><span>${h.status==='finished'?'BANDEIRADA':h.status==='countdown'?'PREPARE-SE':h.status==='admin_paused'?'PAUSADO':'CORRIDA AO VIVO'}</span><strong>${Math.round(progress*100)}%</strong></div></div><aside class="leaderboard"><h2>Classificação</h2>${p.map((x,i)=>`<div class="leader-row ${x.teamId===myId?'mine':''}"><span class="place">${i+1}</span><span class="team-dot" style="background:${x.color}"></span><strong>${esc(x.name)}</strong><span>${x.final?sec(x.final/1000):x.base?sec((x.base+x.adjust)/1000):'—'}</span></div>`).join('')}<p class="leader-note">Tempos oficiais definidos pelo servidor. A animação apenas mostra o progresso.</p></aside></div>${e&&e.status==='open'?`<div class="qte-overlay ${eligible?'eligible':''}"><div class="qte-card"><small>Duelo de ultrapassagem</small><h2>${eligible?'Sua chance de reagir':`${esc(h.participants.find(x=>x.teamId===e.front)?.name)} × ${esc(h.participants.find(x=>x.teamId===e.behind)?.name)}`}</h2><p>${e.type==='reaction'?'Pressione ESPAÇO quando aparecer AGORA.':e.type==='precision'?'Pressione ESPAÇO quando o marcador estiver no centro.':'Pressione A, depois D, depois ESPAÇO.'}</p><div class="qte-signal" id="qte-signal">${Date.now()+serverOffset<e.opensAt?'AGUARDE':'AGORA'}</div>${e.type==='precision'?'<div class="precision-bar"><i id="precision-marker"></i><b></b></div>':''}${eligible?'<button class="primary" data-action="qte-touch">Responder</button>':'<small>Assistindo ao duelo</small>'}</div></div>`:''}<div class="race-events"><h2>Ocorrências</h2>${h.history.slice(-5).reverse().map(x=>`<span>${esc(x.type==='qte'?'Duelo concluído':x.type==='qte_open'?'Duelo iniciado':'Largada oficial')} · ${new Date(x.at).toLocaleTimeString('pt-BR')}</span>`).join('')}</div></section>`;}
function results(){const heats=state.heats,final=heats.find(h=>h.type==='final'&&h.status==='finished'),qual=heats.filter(h=>h.type==='qualifier'&&h.status==='finished');const h=final||qual.at(-1);if(!h)return `<section class="content narrow"><div class="eyebrow">Resultados</div><h1>A bandeirada ainda não caiu.</h1><p>Os tempos oficiais aparecem depois de cada bateria.</p></section>`;return `<section class="content"><div class="page-head"><div><div class="eyebrow">Resultado oficial</div><h1>${final?'Pódio da grande final':'Classificação da bateria'}</h1><p>Menor tempo em três voltas, incluindo desgaste e efeitos válidos dos duelos.</p></div></div><div class="podium">${h.participants.slice(0,3).map((p,i)=>`<div class="podium-place p${i+1}"><span>${i+1}º</span><strong>${esc(p.name)}</strong><small>${sec(p.final/1000)}</small></div>`).join('')}</div><article class="panel"><h2>Classificação completa</h2>${h.participants.map((p,i)=>`<div class="result-row"><span>${p.rank||i+1}º</span><span class="team-dot" style="background:${p.color}"></span><strong>${esc(p.name)}</strong><span>${sec(p.base/1000)} base</span><span>${p.adjust>=0?'+':''}${sec(p.adjust/1000)} duelo</span><b>${sec(p.final/1000)}</b></div>`).join('')}</article>${state.own&&state.room.phase==='RESULTS'?`<article class="panel"><h2>Reflexão final</h2><form id="reflection-form"><label>Qual decisão você manteria?<input name="keep" maxlength="240" value="${esc(state.own.analysis.keep||'')}"></label><label>O que mudaria em uma próxima corrida?<input name="next" maxlength="240" value="${esc(state.own.analysis.next||'')}"></label><button type="submit">Salvar reflexão</button></form></article>`:''}</section>`;}
function projection(){return `<div class="projection">${race()}</div>`;}
function demo(){const t=newTeam('demo','teacher','Carro de demonstração','#f05d5e',0);t.pilot=ui.demo.pilot;t.mechanic=ui.demo.mechanic;t.parts={...ui.demo.parts};const level=MECHANICS.find(m=>m.id===t.mechanic)?.level||1,invalid=SLOTS.filter(s=>PARTS[s].find(p=>p.id===t.parts[s]).level>level),cost=fixedCost(t),op=operating(t,state.room.market),r=simulate(t,state.room.circuitId,1);return `<section class="content"><div class="page-head"><div><div class="eyebrow">Demonstração do professor</div><h1>Mostre uma hipótese na prática.</h1><p>Este carro fictício é calculado localmente para discussão. Não entra no saldo, nos testes nem na classificação da turma.</p></div><div class="phase-tag">Sem resultado oficial</div></div><div class="demo-layout"><article class="panel"><h2>Monte o exemplo</h2><div class="demo-fields"><label>Piloto<select data-demo="pilot">${PILOTS.map(x=>`<option value="${x.id}" ${t.pilot===x.id?'selected':''}>${x.name} · ${cr(x.price)}</option>`).join('')}</select></label><label>Mecânico<select data-demo="mechanic">${MECHANICS.map(x=>`<option value="${x.id}" ${t.mechanic===x.id?'selected':''}>${x.name} · nível ${x.level}</option>`).join('')}</select></label>${SLOTS.map(s=>`<label>${SLOT_NAMES[s]}<select data-demo="${s}">${PARTS[s].map(x=>`<option value="${x.id}" ${t.parts[s]===x.id?'selected':''}>${x.name} · ${cr(x.price)} · nível ${x.level}</option>`).join('')}</select></label>`).join('')}</div></article><article class="panel"><h2>O que acontece?</h2><div class="demo-time">${sec(r.total)} <small>/ volta</small></div><p>Investimento fixo: ${cr(cost)} · Operação mínima: ${cr(op.minimum)} · Saldo teórico: ${cr(1200-cost-op.minimum)}</p>${invalid.length?`<div class="notice">Esta combinação é inválida: ${invalid.map(s=>SLOT_NAMES[s]).join(', ')} exige mecânico de nível maior.</div>`:cost+op.minimum>1200?'<div class="notice">Esta combinação ultrapassa o orçamento inicial.</div>':'<div class="notice success">Combinação viável para testar a hipótese.</div>'}<div class="sector-chart">${r.sectors.map(s=>`<div class="chart-row"><span>${s.index} · ${{R:'Reta',C:'Curva',M:'Misto'}[s.type]}</span><div><i style="width:${Math.min(100,s.seconds/10*100)}%"></i></div><strong>${sec(s.seconds)}</strong></div>`).join('')}</div></article></div></section>`;}
function assignmentPanel(){if(state.room.phase!=='LOCK_IN')return '';const teams=state.roster,count=Math.ceil(teams.length/state.room.carsPerHeat);return `<section class="content" style="padding-top:0"><article class="panel"><h2>Distribuir baterias manualmente</h2><p>Até ${state.room.carsPerHeat} carros por bateria. Cada equipe aparece uma vez. Use “Criar baterias” no topo para distribuição automática.</p><form id="assignments-form" class="assignment-form">${teams.map((t,i)=>`<label><span class="team-dot" style="background:${t.color}"></span>${esc(t.name)}<select name="${t.id}">${Array.from({length:count},(_,j)=>`<option value="${j+1}" ${Math.floor(i/state.room.carsPerHeat)===j?'selected':''}>Bateria ${j+1}</option>`).join('')}</select></label>`).join('')}<button class="primary" type="submit">Confirmar distribuição manual</button></form></article></section>`;}
function awardResultPanel(){const entries=Object.entries(state.awards||{}).filter(([,teamId])=>state.roster.some(t=>t.id===teamId));if(!entries.length)return '';const labels={champion:'Campeão da Pista',evolution:'Maior Evolução',strategist:'Melhor Estrategista',analyst:'Melhor Analista'};return `<section class="content" style="padding-top:0"><article class="panel"><h2>Reconhecimentos</h2><div class="award-grid">${entries.map(([kind,teamId])=>`<div><small>${labels[kind]||kind}</small><strong>${esc(state.roster.find(t=>t.id===teamId)?.name||'')}</strong></div>`).join('')}</div></article></section>`;}
function accessPanel(){return `<section class="content" style="padding-top:0"><article class="panel"><h2>Acesso à sala</h2><p>O código atual vale por 24 horas. A renovação invalida o código anterior; equipes já inscritas continuam na sala.</p><div class="teacher-actions">${button('Renovar código da sala','rotate-access','data-kind="code"')}${button(ui.projectionRefresh?'Gerar novo link de projeção':'Gerar link de projeção','rotate-access','data-kind="projection"')}</div></article></section>`;}
function teacherStatus(){if(!state.teacherTeams?.some(t=>!t.removed))return '';return `<section class="content" style="padding-top:0"><article class="panel"><h2>Evidências das equipes</h2><p>Abra uma escuderia para ver os bloqueios de prontidão e o raciocínio registrado.</p><div class="team-evidence">${state.teacherTeams.filter(t=>!t.removed).map(t=>{const missing=checklist(t),change=compareTests(t.tests[0],t.tests[1]);return `<details><summary><span class="team-dot" style="background:${t.color}"></span><strong>${esc(t.name)}</strong><span>${t.ready?'Pronto':`${missing.length} pendência(s)`}</span></summary><div class="evidence-body"><p><b>Teste 1:</b> ${t.tests[0]?sec(t.tests[0].result.total):'pendente'} · <b>Teste 2:</b> ${t.tests[1]?sec(t.tests[1].result.total):'pendente'} ${change?`· <b>Variação:</b> ${sec(change.delta)} (${change.percent.toFixed(1)}%)`:''}</p><p><b>Hipótese:</b> ${esc([t.analysis.target,t.analysis.change,t.analysis.reason].filter(Boolean).join(' · ')||'pendente')}</p><p><b>Conclusão:</b> ${esc(t.analysis.evidence||'pendente')}</p>${missing.length?`<ul>${missing.map(m=>`<li>${esc(m)}</li>`).join('')}</ul>`:'<p>Requisitos atendidos.</p>'}</div></details>`}).join('')}</div></article></section>`;}
function repeatControls(){if(ui.screen!=='teacher')return '';const cancelled=state.heats.filter(h=>h.status==='cancelled'&&!state.heats.some(x=>x.repeatOf===h.id));const qualifiers=state.heats.filter(h=>h.type==='qualifier'),canFinal=state.room.phase==='QUALIFYING'&&qualifiers.some(h=>h.status==='cancelled')&&qualifiers.some(h=>h.status==='finished')&&qualifiers.every(h=>['finished','cancelled'].includes(h.status));if(!cancelled.length&&!canFinal)return '';return `<section class="content" style="padding-top:0"><article class="panel"><h2>Incidentes de corrida</h2>${cancelled.map(h=>`<div class="heat-row"><span>${h.type==='final'?'Final':`Classificatória ${h.number}`} cancelada</span>${button('Criar repetição','race-command',`data-heat="${h.id}" data-command="repeat"`)}</div>`).join('')}${canFinal?button('Criar final com baterias concluídas','build-final','class="primary"'):''}</article></section>`;}
function returnActions(){const t=state.own;if(!t||!['TEAM_BUILD','TESTING'].includes(state.room.phase))return '';
  if(ui.screen==='team')return `<section class="content" style="padding-top:0"><div class="return-actions"><strong>Desfazer contratações</strong>${t.pilot?button('Devolver piloto','choose-staff','data-kind="pilot" data-id=""'):''}${t.mechanic?button('Devolver mecânico','choose-staff','data-kind="mechanic" data-id=""',SLOTS.some(s=>t.parts[s]),'Remova as peças primeiro.'):''}</div></section>`;
  if(ui.screen==='garage'&&t.parts[ui.slot])return `<section class="content" style="padding-top:0"><div class="return-actions"><strong>${SLOT_NAMES[ui.slot]} instalado</strong>${button('Devolver esta peça','remove-part',`data-slot="${ui.slot}"`)}</div></section>`;
  return '';
}
function awardPanel(){if(!['FINAL','RESULTS'].includes(state.room.phase)||!state.teacherTeams?.length)return '';return `<section class="content" style="padding-top:0"><article class="panel"><h2>Reconhecimentos pedagógicos</h2><p>Escolha manualmente as equipes com base nas hipóteses, métricas e justificativas.</p><div class="split">${[['strategist','Melhor Estrategista'],['analyst','Melhor Analista']].map(([kind,label])=>`<form class="award-form" data-kind="${kind}"><label>${label}<select name="teamId"><option value="">Selecione uma equipe</option>${state.teacherTeams.filter(t=>!t.removed).map(t=>`<option value="${t.id}" ${state.awards[kind]===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><button type="submit">Atribuir</button></form>`).join('')}</div></article></section>`;}
function rules(){return `<section class="content narrow"><div class="eyebrow">Regras do jogo</div><h1>Decida com evidências.</h1><div class="rules-list"><h2>Orçamento</h2><p>Todas as equipes começam com 1.200 Cr. Trocas antes da trava devolvem o preço originalmente pago. Você não pode gastar além do saldo.</p><h2>Projeto</h2><p>Se uma peça exige nível 3, então você precisa de mecânico especialista. Se a eficiência final fica abaixo de 35, o motor consome uma unidade extra de combustível.</p><h2>Teste controlado</h2><p>Faça uma volta, anote o gargalo e repita. Você pode manter o projeto ou alterar uma variável. Compare tempos, custo fixo e custo operacional.</p><h2>Corrida</h2><p>O carro segue automaticamente por 3 voltas. Velocidade e aceleração pesam nas retas; controle e estabilidade pesam nas curvas. Confiabilidade reduz desgaste.</p><h2>Duelos</h2><p>Quando carros próximos se encontram, um desafio rápido pode alterar o tempo oficial. A resposta só vale na janela e é validada pelo servidor. O professor pode desativar os duelos para toda a sala.</p><h2>Glossário</h2><p><b>Custo fixo:</b> peças e profissionais. <b>Custo variável:</b> suprimentos e testes pagos. <b>Hipótese:</b> previsão testável. <b>Log:</b> registro de cada setor. <b>Valor marginal:</b> ganho obtido por créditos extras.</p></div>${button('Voltar','back','class="secondary"')}</section>`;}
function connectionNotice(){return ui.connectionError?`<div class="connection-notice" role="alert"><span>Não foi possível atualizar a sala: ${esc(ui.connectionError)} Seu progresso continua salvo.</span>${button('Tentar novamente','retry-load')}${user?.role==='teacher'?button('Entrar novamente','reauth'):''}</div>`:'';}
function render(){if(!app)return;document.body.classList.toggle('reduced-motion',ui.reduceMotion);if(!state){app.innerHTML=topbar()+connectionNotice()+(ui.screen==='join'?join():ui.screen==='teacher-login'?teacherLogin():ui.screen==='create'?createRoom():ui.screen==='rules'?rules():welcome())+(ui.toast?`<div class="toast" role="alert">${esc(ui.toast)}</div>`:'');return;}
  const content={overview,team,garage,market,tests,prep,race,results,teacher,demo,projection,rules}[ui.screen]||overview;app.innerHTML=topbar()+connectionNotice()+(ui.screen==='projection'?'':nav())+content()+returnActions()+(ui.screen==='teacher'?assignmentPanel()+teacherStatus()+repeatControls()+awardPanel()+accessPanel():'')+(ui.screen==='results'?awardResultPanel():'')+(ui.toast?`<div class="toast" role="alert">${esc(ui.toast)}</div>`:'');animateCars();}
function animateCars(){const h=activeHeat(),path=document.getElementById('track-path');if(!h||!path)return;const length=path.getTotalLength(),tick=()=>{if(!document.contains(path))return;const elapsed=h.startAt?Math.max(0,Date.now()+serverOffset-h.startAt-h.pauseTotal-(h.pausedAt?Date.now()+serverOffset-h.pausedAt:0)):0;for(const p of h.participants){let progress=0;if(p.sectorTimes?.length){let remaining=elapsed;for(let lap=0;lap<18;lap++){const duration=p.sectorTimes[lap]||1;if(remaining>=duration){progress=(lap+1)/18;remaining-=duration;}else{progress=(lap+remaining/duration)/18;break;}}}const point=path.getPointAtLength((progress%1)*length);const car=document.querySelector(`[data-car="${p.teamId}"]`);if(car)car.setAttribute('transform',`translate(${point.x} ${point.y})`);}if(!ui.reduceMotion)requestAnimationFrame(tick);};tick();}
app.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;
  if(a==='show-join')setScreen('join');else if(a==='show-teacher')setScreen('teacher-login');else if(a==='retry-load')await load();else if(a==='open-room')await openRoom(el.dataset.room);else if(a==='reauth'){state=null;ui.screen='teacher-login';render();}else if(a==='home')setScreen(!state?'welcome':state.room.teacherId===user?.id?'teacher':'overview');else if(a==='nav'&&el.dataset.screen==='rooms'){state=null;ui.screen='create';await loadTeacherRooms();render();}else if(a==='nav')setScreen(el.dataset.screen);else if(a==='rules'){ui.previous=ui.screen;setScreen('rules');}else if(a==='back')setScreen(ui.previous||'overview');else if(a==='motion'){ui.reduceMotion=!ui.reduceMotion;localStorage.setItem('ft_reduce',ui.reduceMotion?'1':'0');render();}else if(a==='slot'){ui.slot=el.dataset.slot;render();}else if(a==='test-view'){ui.testView=el.dataset.view;render();}
  else if(a==='choose-staff')await mutate('team-action',{kind:el.dataset.kind,itemId:el.dataset.id});
  else if(a==='choose-aux')await mutate('team-action',{kind:'aux',enabled:!state.own.aux});
  else if(a==='choose-part')await mutate('equip-part',{slot:el.dataset.slot,partId:el.dataset.id});
  else if(a==='remove-part')await mutate('unequip-part',{slot:el.dataset.slot});
  else if(a==='buy-supply')await mutate('purchase-supply',{kind:el.dataset.kind,quantity:1,marketPhase:state.room.market});
  else if(a==='refund-supply')await mutate('refund-supply',{lotId:el.dataset.lot,quantity:1});
  else if(a==='assign-repair')await mutate('assign-repair',{enabled:!state.own.repairAssigned});
  else if(a==='run-test'){const r=await mutate('run-test');if(r)ui.testView='summary';}
  else if(a==='ready')await mutate('set-ready',{ready:!state.own.ready});
  else if(a==='transition')await mutate('room-transition',{phase:el.dataset.phase});
  else if(a==='market-next')await mutate('market-action',{phase:state.room.market==='M0'?'M1':'M2'});
  else if(a==='build-heats')await mutate('build-heats');else if(a==='build-final')await mutate('build-final');
  else if(a==='race-command')await mutate('race-action',{heatId:el.dataset.heat,command:el.dataset.command});
  else if(a==='rotate-access'){const data=await mutate('rotate-access',{kind:el.dataset.kind});if(data?.kind==='projection'){ui.projectionRefresh=data.token;sessionStorage.setItem('ft_projection',data.token);render();}else if(data?.kind==='code')toast('Código renovado. Compartilhe o novo código com a turma.');}
  else if(a==='remove-team'){const team=state?.roster.find(t=>t.id===el.dataset.team);if(team&&window.confirm(`Excluir a escuderia "${team.name}" da sala? A vaga e o nome serão liberados. O progresso ficará no histórico e esta inscrição perderá acesso.`)){const result=await mutate('remove-team',{teamId:team.id});if(result)toast('Escuderia excluída da sala.');}}
  else if(a==='export'){try{const data=await call('export-session',{roomId:ui.roomId});const blob=new Blob(['\uFEFF'+data.csv],{type:'text/csv;charset=utf-8'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='formula-tech-resultados.csv';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);}catch(e){toast(e.message);}}
  else if(a==='open-projection'){window.open(`${location.origin}/?room=${ui.roomId}&projection=${ui.projectionRefresh}`,'_blank');}
  else if(a==='qte-touch')await answerQte('SPACE');
});
app.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,values=Object.fromEntries(new FormData(f));
  if(f.id==='join-form'){if(ui.busy)return;ui.busy=true;render();try{if(!user)user=(await call('student-auth')).user;const result=await call('join-room',{code:values.code.toUpperCase(),teamName:values.teamName,color:values.color},id());ui.roomId=result.roomId;localStorage.setItem('ft_room',ui.roomId);ui.screen='overview';await load();}catch(x){toast(x.message);}finally{ui.busy=false;render();}}
  else if(f.id==='login-form'){try{user=(await call('teacher-login',{email:values.email,password:values.password})).user;await loadTeacherRooms();if(ui.roomId){ui.screen='teacher';await load();if(state?.room.teacherId===user.id)return;}ui.screen='create';render();}catch(x){toast(x.message);}}
  else if(f.id==='create-form'){try{const data=await call('create-room',{name:values.name,circuitId:values.circuitId,maxPlayers:Number(values.maxPlayers),carsPerHeat:Number(values.carsPerHeat),mode:values.mode,qteEnabled:!!values.qteEnabled});ui.roomId=data.roomId;ui.projectionRefresh=data.projectionToken;localStorage.setItem('ft_room',data.roomId);sessionStorage.setItem('ft_projection',data.projectionToken);ui.screen='teacher';await load();}catch(x){toast(x.message);}}
  else if(f.id==='hypothesis-form')await mutate('submit-analysis',{target:values.target,change:values.change,reason:values.reason});
  else if(f.id==='conclusion-form')await mutate('submit-analysis',{evaluation:values.evaluation,evidence:values.evidence});
  else if(f.id==='reflection-form')await mutate('submit-analysis',{keep:values.keep,next:values.next});
  else if(f.id==='assignments-form'){const groups=Array.from({length:Math.ceil(state.roster.length/state.room.carsPerHeat)},()=>[]);for(const [teamId,group] of Object.entries(values))groups[Number(group)-1]?.push(teamId);await mutate('build-heats',{assignments:groups});}
  else if(f.classList.contains('award-form'))await mutate('award',{kind:f.dataset.kind,teamId:values.teamId});
});
app.addEventListener('change',e=>{const field=e.target.dataset.demo;if(!field)return;if(field==='pilot'||field==='mechanic')ui.demo[field]=e.target.value;else if(SLOTS.includes(field))ui.demo.parts[field]=e.target.value;render();});
function answerQte(key){const h=activeHeat(),e=h?.event;if(!e||e.status!=='open'||![e.front,e.behind].includes(state.own?.id))return;qteQueue=qteQueue.then(async()=>{try{await call('submit-qte',{roomId:ui.roomId,eventId:e.id,key},id());await load();}catch(x){toast(x.message);}});}
document.addEventListener('keydown',e=>{if(!state||!['race','projection'].includes(ui.screen))return;const key=e.code==='Space'?'SPACE':e.key.toUpperCase();if(!['SPACE','A','D'].includes(key))return;if(document.activeElement?.matches('input,textarea,select'))return;e.preventDefault();if(e.repeat)return;answerQte(key);});
async function heartbeat(){if(!state||!ui.roomId||polling)return;polling=true;try{const h=activeHeat();if(h&&['countdown','running','qte_paused'].includes(h.status)&&!ui.projectionToken)await call('sync-race',{roomId:ui.roomId,heatId:h.id},id()).catch(()=>{});await load();}catch{}finally{polling=false;}}
setInterval(()=>{if(!state)return;const e=activeHeat()?.event,signal=document.getElementById('qte-signal');if(!e||!signal)return;const timestamp=Date.now()+serverOffset,open=timestamp>=e.opensAt;signal.textContent=open?'AGORA':'AGUARDE';signal.classList.toggle('now',open);const marker=document.getElementById('precision-marker');if(marker)marker.style.left=`${Math.max(0,Math.min(100,(timestamp-e.opensAt)/2000*100))}%`;},60);
async function boot(){await auth();if(ui.roomId)await load();if(!ui.roomId&&user?.role==='teacher'){ui.screen='create';await loadTeacherRooms();}render();poll=setInterval(heartbeat,1000);}
boot();
